CREATE TABLE IF NOT EXISTS participants(id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, public_key BYTEA NOT NULL, status TEXT NOT NULL, capabilities JSONB NOT NULL, revision BIGINT NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE(organization_id,id));
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, state TEXT NOT NULL, metric TEXT NOT NULL, participants JSONB NOT NULL, epsilon DOUBLE PRECISION NOT NULL, spent DOUBLE PRECISION NOT NULL, deadline TIMESTAMPTZ NOT NULL, revision BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_entries(id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, task_id TEXT, action TEXT NOT NULL, actor TEXT NOT NULL, previous_hash TEXT NOT NULL, hash TEXT NOT NULL, detail TEXT NOT NULL, at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY, aggregate_id TEXT NOT NULL, event_type TEXT NOT NULL, payload JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL, published_at TIMESTAMPTZ);
